resumen.skeleton:
% ARQUITECTURA RESUMEN (reporte contenedor; el producto es el texto mismo):
\section{Introducci\'on}
% Aborda de manera GENERAL el tema a resumir y anuncia el recorrido. Es el elemento
% oficial (1) del fasciculo #17. Sin metadiscurso ni mencion de la actividad.

\section{<Titulo tematico del desarrollo, p.ej. Los derechos humanos y sus garantias en la CPEUM>}
% Elemento oficial (2): parte MEDULAR. Se explican con palabras propias las ideas
% principales del texto base, organizadas en subsecciones que siguen su estructura.
\subsection{<Eje 1, p.ej. Derechos de igualdad y sus garantias>}
% Cada afirmacion sustantiva ancla su fundamento normativo exacto y su \citep.
\subsection{<Eje 2, p.ej. Derechos de libertad y sus garantias>}
\subsection{<Eje 3, p.ej. Legalidad y seguridad juridica>}
\subsection{<Eje 4, p.ej. Derechos sociales y sus garantias>}

\clearpage\section{Conclusi\'on}
% Elemento oficial (3): cierra con SINTESIS de las ideas presentadas + postura propia.
% IA como \footnote ligada a una frase oportuna.
\clearpage\bibliography{<materia>}

resena.skeleton:
% ARQUITECTURA VALIDADA (reporte contenedor + producto resena anidado):
% Preambulo: \usepackage[most]{tcolorbox} + \newtcolorbox{resenabox} + \fichabibliografica.
\section{Introducci\'on}
% Del REPORTE: contextualiza el TEMA (no la actividad), anuncia el enfoque. Sin metadiscurso.

\section{<Titulo tematico del marco, p.ej. Marco juridico y fundamento...>}
% MARCO CONCEPTUAL que gravita AFUERA del recuadro: subsecciones tematicas con los
% conceptos del extractor + sus citas de sustento (referencias externas).
\subsection{<Eje conceptual 1 del extractor>}<def con \textbf + \citep de sustento>
\subsection{<Eje conceptual 2>}...
\subsection{<Eje conceptual 3>}...
\subsection{<Eje conceptual 4>}...\begin{itemize}...\end{itemize} % 1 lista natural
\subsection{Rese\~na del <objeto resenado>}
Sobre las bases anteriores, se rese\~na <objeto: articulos/obra + vigencia + alcance>.
\begin{resenabox}
\fichabibliografica{<obra>}{<autoria>}{<editorial/fuente>}{<lugar>}{<ano>}{<edicion>}
\medskip{\large\bfseries\color{unadmGreenDark} <Titulo de la resena, distinto al de la obra>\par}\medskip
\textbf{Introducci\'on.} <Describe la temATICA y presenta brevemente la obra/autor. Inicia con el sujeto real, p.ej. 'La Constitucion...'.>

\textbf{<Rotulo tematico 1 de la rubrica>.} <parrafo breve con \citep>
\textbf{<Rotulo tematico 2 (parafrasis)>.} <cita textual de la obra con \enquote + parafrasis>
\textbf{<Rotulo tematico 3 (importancia/reflexion)>.} <reflexion con ejemplos concretos>
\textbf{<Rotulo tematico 4 (legislacion/desarrollo)>.} <desarrollo con \citep>
\textbf{Conclusiones y valoraci\'on.} <juicio critico + \textbf{recomiendo} + cierre>
\end{resenabox}
\clearpage\section{Conclusi\'on}
% Del REPORTE: reflexion sobre el TEMA en 1a persona; IA como \footnote. NO repite la resena.
\clearpage\bibliography{<materia>}

