% ARQUITECTURA MAPA SEMANTICO (reporte contenedor + producto grafico):
% Preambulo: estilos msroot/msfield/msleaf/mslink/mslabel (ver tikz_styles).
\section{Introducci\'on}
% Contextualiza el TEMA CENTRAL y para que sirve el mapa semantico (sintesis visual).

\section{Mapa sem\'antico: <tema central>}
\subsection{Metodolog\'ia de construcci\'on}
% Los 6 pasos del fasciculo: (1) establecer el tema, (2) identificar conceptos clave,
% (3) precisar palabras enlace/conectores, (4) definir jerarquia (deductivo), (5) construir
% la representacion grafica, (6) consultar referencias. En actividades juridicas: relacionar
% cada concepto con su FUNDAMENTO CONSTITUCIONAL (art./fracc./parrafo/inciso).
\begin{enumerate}...\end{enumerate}
\begin{landscape}\thispagestyle{empty}
\subsection{Representaci\'on gr\'afica}
\begin{center}\resizebox{!}{0.80\textheight}{%
\begin{tikzpicture}[node distance=0.55cm and 0.9cm]
% TEMA CENTRAL (nodo raiz)
\node[msroot] (root) {<Tema central, p.ej. Derechos humanos y sus garantias en la Constitucion>};
% CAMPOS SEMANTICOS (ramas radiales en abanico: below left/below right a distancias crecientes)
\node[msfield, below left=1.55cm and 6.4cm of root] (c1) {<Campo 1, p.ej. DH de igualdad>};
\node[msfield, below left=1.55cm and 2.2cm of root] (c2) {<Campo 2, p.ej. DH de libertad>};
\node[msfield, below=1.7cm of root] (c3) {<Campo 3>};
\node[msfield, below right=1.55cm and 2.2cm of root] (c4) {<Campo 4>};
% PALABRAS ENLACE raiz->campo (elemento distintivo: nombran la relacion)
\draw[mslink] (root) -- node[mslabel]{<se clasifican en>} (c1);
\draw[mslink] (root) -- node[mslabel]{<comprenden>} (c2);
% CONCEPTOS por campo, cada uno CON SU FUNDAMENTO CONSTITUCIONAL
\node[msleaf, below=0.6cm of c1] (c1a) {<Concepto> (art.~N, fracc.~X CPEUM)};
\draw[mslink] (c1) -- node[mslabel]{<se funda en>} (c1a);
% ...resto de campos y conceptos...
\end{tikzpicture}}\end{center}
\end{landscape}
\subsection{Lectura del mapa}
% Interpreta el mapa: recorre los campos y explica la correlacion concepto<->fundamento.
\clearpage\section{Conclusi\'on}
% Reflexion en 1a persona sobre lo sintetizado; IA como \footnote.
\clearpage\bibliography{<materia>}

